def consulta():
    filas = [[L(a, b), '', '', '', ''] for a, b in [('Hilera / bloque', 'Row / block'), ('Parcela y tratamiento', 'Plot and treatment'), ('Planta (número)', 'Vine (number)'), ('Edad (años)', 'Age (years)'), ('Sarmiento más largo (cm)', 'Longest shoot (cm)'), ('Peso de poda (kg)', 'Pruning weight (kg)'), ('NDVI', 'NDVI'), ('Potencial de tallo (MPa)', 'Stem potential (MPa)'), ('Riego (L por planta)', 'Irrigation (L per vine)'), ('Floración / envero (fecha)', 'Flowering / veraison (date)'), ('Racimos', 'Clusters'), ('Rendimiento (kg)', 'Yield (kg)'), ('°Brix', '°Brix')]]
    c = P('Imprime esta hoja y llévala al viñedo; una columna por visita. Lo que anotes aquí es lo que capturas en los bloques 4 a 7 y en la plantilla del Bloque 9.',
          'Print this sheet and take it to the vineyard; one column per visit. What you write here is what you enter in blocks 4 to 7 and in the Block 9 sheet.')
    c += TABLA([('Variable', 'Variable'), ('Visita 1', 'Visit 1'), ('Visita 2', 'Visit 2'), ('Visita 3', 'Visit 3'), ('Visita 4', 'Visit 4')], filas, 'hoja')
    s = CHAP('hoja', 'A', 'var(--acc)', 'Consulta', 'Reference', 'Hoja de campo', 'Field sheet', 'Para anotar en el viñedo.', 'For notes in the vineyard.', c, inchap=False)
    c = TABLA([('Lo que ves', 'What you see'), ('Por qué', 'Why'), ('Qué hacer', 'What to do')], [
        [('«sin dato» en un resultado', '“no data” in a result'), ('Falta una captura en un bloque anterior.', 'An entry is missing in an earlier block.'), ('El aviso dice cuál; tócalo para ir ahí.', 'The notice says which; tap it to go there.')],
        [('El balance no aparece', 'The balance does not appear'), ('Faltan clima, sitio, tipo de uva, suelo, etapas o brotación.', 'Climate, site, grape type, soil, stages or budburst missing.'), ('El Bloque 4 lista lo que falta.', 'Block 4 lists what is missing.')],
        [('El CSV de clima no se importa', 'The climate CSV will not import'), ('Faltan las columnas de fecha, Tmáx o Tmín, o hay Tmáx menor que Tmín.', 'Date, Tmax or Tmin columns missing, or Tmax below Tmin.'), ('Revisa los encabezados; la app dice cuántas filas descartó.', 'Check the headers; the app says how many rows it dropped.')],
        [('Un índice dice «cobertura»', 'An index reads “coverage”'), ('Su periodo tiene menos de 90 % de días con dato.', 'Its period has under 90 % of days with data.'), ('Completa los registros de ese periodo.', 'Fill in that period’s records.')],
        [('Los datos desaparecieron', 'The data disappeared'), ('Se borró la memoria del navegador o cambiaste de equipo.', 'Browser storage was cleared or you changed device.'), ('Abre tu último archivo de proyecto.', 'Open your last project file.')]])
    s += CHAP('problemas', 'B', 'var(--acc)', 'Consulta', 'Reference', 'Si algo no sale', 'If something goes wrong', 'Problemas frecuentes y su arreglo.', 'Common problems and their fix.', c, inchap=False)
    s += CHAP('glosario', 'C', 'var(--acc)', 'Consulta', 'Reference', 'Glosario', 'Glossary', 'Las palabras del viñedo medido.', 'The words of the measured vineyard.', '<dl class="glos" id="glos"></dl>\n', inchap=False)
    c = rapido() + f'<div class="qrbox">{qr_svg()}' + P('Escanea para abrir Ratio Vitis:<br><b>hectortecumshe-ai.github.io/RatioVitis</b>', 'Scan to open Ratio Vitis:<br><b>hectortecumshe-ai.github.io/RatioVitis</b>') + '</div>\n'
    s += CHAP('unapagina', 'D', 'var(--acc)', 'Consulta', 'Reference', 'Ratio Vitis en una página', 'Ratio Vitis on one page', 'Los 16 bloques en una frase cada uno.', 'The 16 blocks in one sentence each.', c, inchap=False)
    c = '<h3 id="cita-app">' + L('Cómo citar la aplicación', 'How to cite the app') + '</h3>\n' + cita_app()
    c += '<h3 id="cita-guia">' + L('Cómo citar este instructivo', 'How to cite this guide') + '</h3>\n' + cita_guia('productor', T_ES, T_EN)
    c += '<h3 id="fuentes-caso">' + L('Fuentes del caso', 'Case sources') + '</h3>\n'
    c += P('Mojica-Zárate, H. T., Barrera-Guzmán, L. Á., Alejo-Bello, S., Partida-Sedas, J. G., Rojas-Reyes, J. O., Díaz-José, O., Tinoco-Rueda, J. Á., y Torres-Palacios, C. (2026). <i>Guía práctica para el establecimiento de uva en Mata de Zarza, Veracruz</i>. Universidad Autónoma Chapingo.<br>Hernández González, J. (2026). <i>Adaptabilidad del cultivo de uva (Vitis vinifera L.) en Mata de Zarza, Veracruz, como sistema complejo adaptativo</i> (propuesta de tesis de maestría). Universidad Autónoma Chapingo.<br>Hersbach, H., et al. (2020). The ERA5 global reanalysis. <i>Quarterly Journal of the Royal Meteorological Society, 146</i>(730), 1999–2049. https://doi.org/10.1002/qj.3803',
           'Mojica-Zárate, H. T., Barrera-Guzmán, L. Á., Alejo-Bello, S., Partida-Sedas, J. G., Rojas-Reyes, J. O., Díaz-José, O., Tinoco-Rueda, J. Á., &amp; Torres-Palacios, C. (2026). <i>Guía práctica para el establecimiento de uva en Mata de Zarza, Veracruz</i>. Chapingo Autonomous University.<br>Hernández González, J. (2026). <i>Adaptabilidad del cultivo de uva (Vitis vinifera L.) en Mata de Zarza, Veracruz, como sistema complejo adaptativo</i> (master’s thesis proposal). Chapingo Autonomous University.<br>Hersbach, H., et al. (2020). The ERA5 global reanalysis. <i>Quarterly Journal of the Royal Meteorological Society, 146</i>(730), 1999–2049. https://doi.org/10.1002/qj.3803')
    c += '<h3 id="ficha">' + L('Ficha', 'Imprint') + '</h3>\n' + legal('productor', T_ES, T_EN)
    s += CHAP('creditos', 'E', 'var(--acc)', 'Consulta', 'Reference', 'Cómo citar y créditos', 'How to cite and credits', 'Autores, licencias y fuentes del caso.', 'Authors, licences and case sources.', c, inchap=False)
