def armar():
    otra = L('Hay otra guía para investigación y docencia: el <a href="instructivo-cientifico.html">Instructivo del Científico</a>.', 'There is a companion guide for research and teaching: the <a href="instructivo-cientifico.html">Scientist Guide</a>.')
    cuerpo = portada('productor', T_ES, T_EN, 'El viñedo <em>que se mide</em> <span class="a">del suelo al aire</span>', 'The vineyard <em>you measure</em> <span class="a">from soil to air</span>',
                     'Una guía práctica para medir tu viñedo con Ratio Vitis —suelo, clima, agua, nutrición, biomasa, cosecha y energía— y leerlo como un sistema que se puede comparar y proyectar.',
                     'A practical guide to measuring your vineyard with Ratio Vitis —soil, climate, water, nutrition, biomass, harvest and energy— and reading it as a system you can compare and project.', 'balance', 'diseno', otra)
    cuerpo += '<div class="doc">\n' + preliminares() + empezar() + b1() + b2() + b3() + b4() + b5() + b6() + b7() + b8() + b9() + b10() + b11_16() + consulta() + '</div>\n'
    html = pagina('productor', cuerpo, T_ES, T_EN, 'Instructivo del Productor', 'Producer Guide', 'RatioVitis-Instructivo-Productor.pdf', 'RatioVitis-Producer-Guide.pdf',
                  {'leer': ['Para empezar', 'Getting started'], 'b1': ['Los dieciséis bloques', 'The sixteen blocks'], 'hoja': ['Consulta', 'Reference']}, GLOS,
                  'Instructivo del Productor de Ratio Vitis: mide tu viñedo del suelo al aire, con el caso de Mata de Zarza, Veracruz. · Ratio Vitis Producer Guide.')
    escribir('instructivo-productor.html', html)
